import{_ as e,c as o,o as i,ag as l}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"故障排查","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/troubleshooting.md","filePath":"zh-CN/guide/troubleshooting.md","lastUpdated":1791311600000}'),r={name:"zh-CN/guide/troubleshooting.md"};function t(d,a,n,h,c,s){return i(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h1><p>本页汇总 nPlyr 在 macOS 与 iOS 上的常见问题及解决方法。</p><h2 id="应用无法启动或启动即崩溃" tabindex="-1">应用无法启动或启动即崩溃 <a class="header-anchor" href="#应用无法启动或启动即崩溃" aria-label="Permalink to &quot;应用无法启动或启动即崩溃&quot;">​</a></h2><ol><li>确认你的系统满足最低要求（macOS 14 Sonoma 及以上，或 iOS / iPadOS 16 及以上）。</li><li>退出并重新启动应用。</li><li>如果你侧载了开发版本，请确认描述文件仍然有效。</li></ol><h2 id="视频无法播放-一直转圈或报错" tabindex="-1">视频无法播放（一直转圈或报错） <a class="header-anchor" href="#视频无法播放-一直转圈或报错" aria-label="Permalink to &quot;视频无法播放（一直转圈或报错）&quot;">​</a></h2><ul><li>确认链接是一个<strong>直链</strong>媒体 URL（<code>mp4</code>、<code>m3u8</code>、<code>flv</code>、<code>ts</code> 等），而不是一个页面。使用<a href="/zh-CN/guide/browser.html">浏览器与嗅探器</a>抓取真正的链接。</li><li>某些站点需要特定的<strong>请求头</strong>（referer、cookie、auth）。通过嗅探器抓取链接会自动保留这些请求头。</li><li><code>TS → MP4</code> 透传需要格式提示；如果某个 TS 源失败，请尝试从线路切换器选择另一条线路。</li><li>来自源的 <code>403</code> 通常是短暂的站点侧限流；请等待后重试，而不是盲目更改请求头。</li></ul><h2 id="嗅探器在某个网站上什么也抓不到" tabindex="-1">嗅探器在某个网站上什么也抓不到 <a class="header-anchor" href="#嗅探器在某个网站上什么也抓不到" aria-label="Permalink to &quot;嗅探器在某个网站上什么也抓不到&quot;">​</a></h2><ul><li>该页面可能通过专有播放器或 DRM 加载视频，从不请求普通媒体文件。此时，与该源 API 通信的<a href="/zh-CN/guide/miniapps.html">小程序</a>才是正确的工具。</li><li>尝试重新加载页面，或在<a href="/zh-CN/guide/settings.html">设置</a>中将<strong>浏览器 user-agent</strong>切换到移动端 / 桌面端。</li></ul><h2 id="某个键盘快捷键不起作用" tabindex="-1">某个键盘快捷键不起作用 <a class="header-anchor" href="#某个键盘快捷键不起作用" aria-label="Permalink to &quot;某个键盘快捷键不起作用&quot;">​</a></h2><ul><li>快捷键仅按修饰键匹配（<code>⌘</code>、<code>⌥</code>、<code>⌃</code>、<code>⇧</code>）；方向键与小键盘不属于绑定的一部分。</li><li>当你在文本框（URL 栏、搜索框）中输入时，单键快捷键会被有意抑制，以免与你的输入冲突。</li><li>如果某个绑定依然感觉失效，请检查它是否在<strong>系统设置 → 键盘 → 键盘快捷键</strong>中被系统或应用快捷键遮蔽。</li></ul><h2 id="下载停滞或失败" tabindex="-1">下载停滞或失败 <a class="header-anchor" href="#下载停滞或失败" aria-label="Permalink to &quot;下载停滞或失败&quot;">​</a></h2><ul><li>单个分片失败会将下载标记为 <code>.failed</code>；可从标记文件续传。</li><li>如果某个域名反复返回 <code>404</code>，nPlyr 会在本次会话中将其拉黑，且不会静默改道——请选择另一个源。</li><li>重封装失败会保留原始 <code>.ts</code> 并标记为 <code>completed</code>，因此你的数据不会丢失。</li></ul><h2 id="某个小程序的行为与-android-上不同" tabindex="-1">某个小程序的行为与 Android 上不同 <a class="header-anchor" href="#某个小程序的行为与-android-上不同" aria-label="Permalink to &quot;某个小程序的行为与 Android 上不同&quot;">​</a></h2><p>原始引擎是 Android/Java（Rhino）。nPlyr 在 JavaScriptCore 上运行规则，并为规则所依赖的部分实现了一个 <strong>Rhino→Java 兼容层</strong>。部分 Java 特有的行为是有意不支持的。请查阅<a href="/zh-CN/guide/miniapp-compatibility.html">兼容性</a>页面；如果某条具体规则失败，请报告规则名称。</p><h2 id="重置-nplyr" tabindex="-1">重置 nPlyr <a class="header-anchor" href="#重置-nplyr" aria-label="Permalink to &quot;重置 nPlyr&quot;">​</a></h2><p>你可以从<strong>设置 → 高级 → 重置</strong>重置应用的本地数据（媒体库、书签、小程序变量）。这不会影响你已购买的解锁。</p>',16)])])}const p=e(r,[["render",t]]);export{m as __pageData,p as default};
